package org.json; import java.util.HashMap; public class JSONObject { public static final Object NULL=new Object(); private final HashMap<String,Object> values=new HashMap<>(); public JSONObject put(String k,Object v){values.put(k,v);return this;} public JSONObject put(String k,int v){return put(k,Integer.valueOf(v));} public JSONObject put(String k,long v){return put(k,Long.valueOf(v));} public JSONObject put(String k,boolean v){return put(k,Boolean.valueOf(v));} public Object opt(String k){return values.get(k);} public String toString(){return values.toString();} }
